+        margin: 0 0 28px;
+        color: var(--muted);
+        font-size: 1rem;
+        line-height: 1.6;
+      }
+
+      form {
+        display: grid;
+        gap: 24px;
+      }
+
+      .form-field {
+        padding: 24px;
+        border: 1px solid var(--panel-border);
+        border-radius: 20px;
+        background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
+      }
+
+      fieldset {
+        margin: 0;
+        padding: 0;
+        border: 0;
+      }
+
+      legend {
+        margin: 0 0 18px;
+        padding: 0;
+        font-size: 1.05rem;
+        font-weight: 700;
+      }
+
+      .radio-list {
+        display: grid;
+        gap: 14px;
+      }
+
+      .radio-option {
+        position: relative;
+      }
+
+      .radio-option input {
+        position: absolute;
+        opacity: 0;
+        inset: 0;
+      }
+
+      .radio-option label {
+        display: flex;
+        align-items: center;
+        gap: 14px;
+        width: 100%;
+        padding: 16px 18px;
+        border: 1px solid var(--panel-border);
+        border-radius: 16px;
+        background: #ffffff;
+        cursor: pointer;
+        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
+      }
+
+      .radio-option label::before {
+        content: "";
+        width: 20px;
+        height: 20px;
+        border-radius: 999px;
+        border: 2px solid #8ca0bf;
+        background: #ffffff;
+        transition: all 0.2s ease;
+        flex: 0 0 auto;
+      }
+
+      .radio-option label:hover {
+        border-color: #bfd2f5;
+        transform: translateY(-1px);
+      }
+
+      .radio-option input:focus-visible + label {
+        outline: 3px solid #93c5fd;
+        outline-offset: 3px;
+      }
+
+      .radio-option input:checked + label {
+        border-color: var(--accent);
+        background: var(--accent-soft);
+        box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.14);
+      }
+
+      .radio-option input:checked + label::before {
+        border-width: 6px;
+        border-color: var(--accent);
+      }
+
+      .submit-button {
+        justify-self: start;
+        border: 0;
+        border-radius: 14px;
+        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
+        color: #ffffff;
+        font: inherit;
+        font-weight: 700;
+        padding: 14px 22px;
+        cursor: pointer;
+        box-shadow: 0 14px 28px rgba(37, 99, 235, 0.25);
+        transition: transform 0.2s ease, box-shadow 0.2s ease;
+      }
+
+      .submit-button:hover {
+        transform: translateY(-1px);
+        box-shadow: 0 18px 30px rgba(37, 99, 235, 0.3);
+      }
+
+      .submit-button:focus-visible {
+        outline: 3px solid #93c5fd;
+        outline-offset: 3px;
+      }
+
+      @media (max-width: 480px) {
+        .card {
+          padding: 24px;
+          border-radius: 20px;
+        }
+
+        .form-field {
+          padding: 20px;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .card,
+        .form-field,
+        .radio-option label,
+        .submit-button {
+          border-color: ButtonText;
+        }
+
+        .submit-button {
+          background: ButtonFace;
+          color: ButtonText;
+          box-shadow: none;
+        }
+
+        .radio-option input:checked + label {
+          background: Highlight;
+          color: HighlightText;
+          box-shadow: none;
+        }
+      }
+    </style>
+  </head>
+  <body>
