+      ];
+
+      function RadioOption({ id, label }) {
+        return `
+          <div class="radio-option">
+            <input type="radio" id="${id}" name="notificationPreference" value="${label}" required />
+            <label for="${id}">${label}</label>
+          </div>
+        `;
+      }
+
+      function NotificationForm() {
+        return `
+          <form>
+            <div class="form-field">
+              <fieldset>
+                <legend>How do you prefer to receive notifications?</legend>
+                <div class="radio-list">
+                  ${notificationOptions.map((option) => RadioOption(option)).join("")}
+                </div>
+              </fieldset>
+            </div>
+            <button class="submit-button" type="submit">Submit</button>
+          </form>
+        `;
+      }
+
+      function App() {
+        return `
+          <main class="page-shell">
+            <section class="card" aria-labelledby="page-title">
+              <div class="eyebrow">Account settings</div>
+              <h1 id="page-title">Choose your notification preference</h1>
+              <p class="lead">
+                Pick the one channel you want us to use for important updates and alerts.
+              </p>
+              ${NotificationForm()}
+            </section>
+          </main>
+        `;
+      }
+
+      document.getElementById("root").innerHTML = App();
+    </script>
+  </body>
+</html>
*** End Patch
