    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --panel: #ffffff;
        --panel-border: #d9e2f1;
        --text: #14213d;
        --muted: #5c6b85;
        --accent: #3b82f6;
        --accent-strong: #2563eb;
        --accent-soft: #dbeafe;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #eff6ff 0%, #f4f7fb 45%, #eef2ff 100%);
        color: var(--text);
      }

      .page-shell {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 20px;
      }

      .card {
        width: min(100%, 560px);
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        padding: 32px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: #eef4ff;
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      h1 {
        margin: 18px 0 12px;
        font-size: clamp(1.9rem, 4vw, 2.4rem);
        line-height: 1.1;
      }

      .lead {
        margin: 0 0 28px;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 24px;
      }

      .form-field {
        padding: 24px;
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin: 0 0 18px;
        padding: 0;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .radio-list {
        display: grid;
        gap: 14px;
      }

      .radio-option {
        position: relative;
      }

      .radio-option input {
        position: absolute;
        opacity: 0;
        inset: 0;
      }

      .radio-option label {
        display: flex;
        align-items: center;
        gap: 14px;
        width: 100%;
        padding: 16px 18px;
        border: 1px solid var(--panel-border);
        border-radius: 16px;
        background: #ffffff;
        cursor: pointer;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      .radio-option label::before {
        content: "";
        width: 20px;
        height: 20px;
        border-radius: 999px;
        border: 2px solid #8ca0bf;
        background: #ffffff;
        transition: all 0.2s ease;
        flex: 0 0 auto;
      }

      .radio-option label:hover {
        border-color: #bfd2f5;
        transform: translateY(-1px);
      }

      .radio-option input:focus-visible + label {
        outline: 3px solid #93c5fd;
        outline-offset: 3px;
      }

      .radio-option input:checked + label {
        border-color: var(--accent);
        background: var(--accent-soft);
        box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.14);
      }

      .radio-option input:checked + label::before {
        border-width: 6px;
        border-color: var(--accent);
      }

      .submit-button {
        justify-self: start;
        border: 0;
        border-radius: 14px;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        color: #ffffff;
        font: inherit;
        font-weight: 700;
        padding: 14px 22px;
        cursor: pointer;
        box-shadow: 0 14px 28px rgba(37, 99, 235, 0.25);
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 30px rgba(37, 99, 235, 0.3);
      }

      .submit-button:focus-visible {
        outline: 3px solid #93c5fd;
        outline-offset: 3px;
      }

      @media (max-width: 480px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }

        .form-field {
          padding: 20px;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .radio-option label,
        .submit-button {
          border-color: ButtonText;
        }

        .submit-button {
          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }

        .radio-option input:checked + label {
          background: Highlight;
          color: HighlightText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>
    <script>
      const notificationOptions = [
        { id: "email", label: "Email" },
        { id: "sms", label: "SMS" },
        { id: "push", label: "Push Notifications" },
      ];

      function RadioOption({ id, label }) {
        return `
          <div class="radio-option">
            <input type="radio" id="${id}" name="notificationPreference" value="${label}" required />
            <label for="${id}">${label}</label>
          </div>
        `;
      }

      function NotificationForm() {
        return `
          <form>
            <div class="form-field">
              <fieldset>
                <legend>How do you prefer to receive notifications?</legend>
                <div class="radio-list">
                  ${notificationOptions.map((option) => RadioOption(option)).join("")}
                </div>
              </fieldset>
            </div>
            <button class="submit-button" type="submit">Submit</button>
          </form>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            <section class="card" aria-labelledby="page-title">
              <div class="eyebrow">Account settings</div>
              <h1 id="page-title">Choose your notification preference</h1>
              <p class="lead">
                Pick the one channel you want us to use for important updates and alerts.
              </p>
              ${NotificationForm()}
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();
    </script>
  </body>
</html>
